export function LineIcon({
  name,
  color,
  size,
}: {
  name: LineIconName;
  color: string;
  /** Cỡ vẽ — mặc định đúng khung gốc của file (20, caret 16). */
  size?: number;
}) {
  const icon = XML[name];
  const px = size ?? icon.frame;
  return <SvgXml xml={icon.xml} width={px} height={px} color={color} />;
}
